import re, sys, time
import workcell

def call(tool, *args):
    return workcell.call(tool, *args)

def parse_vision():
    r = call("vision", "locate")
    t = r.text
    v = {}
    m = re.search(r'socket hole centre: x=([-\d.]+) y=([-\d.]+) mm, top at z=([-\d.]+)', t)
    if m: v['hole'] = tuple(float(x) for x in m.groups())
    m = re.search(r'peg: centre x=([-\d.]+) y=([-\d.]+) z=([-\d.]+); lower end x=([-\d.]+) y=([-\d.]+) z=([-\d.]+); tilt ([\d.]+)', t)
    if m: v['peg'] = {'centre':(float(m.group(1)),float(m.group(2)),float(m.group(3))),
                      'low':(float(m.group(4)),float(m.group(5)),float(m.group(6))),
                      'tilt':float(m.group(7))}
    return v, t

def status():
    r = call("robot","status")
    t = r.text
    d = {}
    m = re.search(r'left arm: TCP at x=([-\d.]+) y=([-\d.]+) z=([-\d.]+)', t)
    if m: d['left']=(float(m.group(1)),float(m.group(2)),float(m.group(3)))
    m = re.search(r'right arm: TCP at x=([-\d.]+) y=([-\d.]+) z=([-\d.]+)', t)
    if m: d['right']=(float(m.group(1)),float(m.group(2)),float(m.group(3)))
    return d, t

def step(arm, dx, dy, dz):
    r = call("robot","step", arm, str(dx), str(dy), str(dz))
    return r

def align_peg(tx, ty, tol=0.7, maxit=20, ref='centre'):
    for i in range(maxit):
        v,t = parse_vision()
        cx,cy,cz = v['peg'][ref]
        dx = tx - cx; dy = ty - cy
        if abs(dx) < tol and abs(dy) < tol:
            print(f"aligned iter{i} centre=({cx:.1f},{cy:.1f})")
            return True
        dx = max(-15,min(15,dx)); dy=max(-15,min(15,dy))
        r = step("right", dx, dy, 0)
        print(f"iter{i} err=({tx-cx:.2f},{ty-cy:.2f}) step=({dx:.1f},{dy:.1f}) -> {r.text.strip()}")
    return False

if __name__ == "__main__":
    v,t = parse_vision(); print("VISION:", t)
    s,t2 = status(); print("STATUS:", t2)
